import{_ as t,o as e,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"科学日报 · 2026-10-20（古生物学 / 古生态）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/paleontology/science-daily-2026-10-20.md","filePath":"topics/paleontology/science-daily-2026-10-20.md"}'),r={name:"topics/paleontology/science-daily-2026-10-20.md"};function a(c,o,l,i,d,g){return e(),n("div",null,[...o[0]||(o[0]=[s('<h1 id="科学日报-·-2026-10-20-古生物学-古生态" tabindex="-1">科学日报 · 2026-10-20（古生物学 / 古生态） <a class="header-anchor" href="#科学日报-·-2026-10-20-古生物学-古生态" aria-label="Permalink to &quot;科学日报 · 2026-10-20（古生物学 / 古生态）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-20.md</code> — 第39期 ｜ 科学板块</p></blockquote><hr><h2 id="科学日报-2026-10-20-深度学习-看清-禾本科花粉——重建肯尼亚山-2-5-万年草原生态" tabindex="-1">科学日报 2026-10-20：深度学习&quot;看清&quot;禾本科花粉——重建肯尼亚山 2.5 万年草原生态 <a class="header-anchor" href="#科学日报-2026-10-20-深度学习-看清-禾本科花粉——重建肯尼亚山-2-5-万年草原生态" aria-label="Permalink to &quot;科学日报 2026-10-20：深度学习\\&quot;看清\\&quot;禾本科花粉——重建肯尼亚山 2.5 万年草原生态&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-20.md</code> ｜ DOI: 10.1073/pnas.2607372123</p></blockquote><ul><li>瓶颈：<strong>禾本科（Poaceae）花粉在传统光学显微镜下大多无法区分物种</strong>，于是草原（grassland）演化研究里，花粉这份&quot;最丰富、最连续&quot;的化石记录长期被浪费掉。</li><li>方法：<strong>超分辨显微 + 半监督深度学习</strong>——用已知现代花粉与<strong>未标注化石花粉</strong>一起训练 CNN；再用学到的 CNN 特征做两件事：以 <strong>Shannon 熵</strong>度量形态变异性（→ 分类学多样性估计），用<strong>梯度提升决策树</strong>判别 <strong>C3 / C4</strong> 光合类型。</li><li>流程：先在现代花粉组合上验证，再应用于<strong>肯尼亚山 2.5 万年湖相沉积序列</strong>，把禾本科多样性随时间的变化，与大气 <strong>CO₂ 浓度</strong>、局地<strong>温度/降水</strong>代用指标、<strong>火活动</strong>记录做相关。</li><li>结果： <ul><li>这些山地草原的物种多样性在 <strong>21,500–16,000 年前</strong>大幅下降，恰与<strong>末次冰期最严重的区域降温</strong>同期。</li><li><strong>晚冰期—全新世过渡之后，C4 禾草比例逐渐降低</strong>，与<strong>升温 + 火活动减弱</strong>相关。</li></ul></li><li>洞察（对本库 <code>paleontology</code> / <code>earth-science</code>）：这是&quot;<strong>AI 让原本不可读的记录变得可读</strong>&quot;的范例——<strong>同一批化石、同一台显微镜，换一个解码器（CNN）就解锁了一整个被丢弃的数据维度</strong>。与库内 09-16（用化石前翅复原侏罗纪声景：<strong>从结构读回行为</strong>）是同一母题的两端：一个从<strong>形态</strong>读回感官生态，一个从<strong>形态变异</strong>读回物种多样性与光合类型。也与 <code>paleoanthropology</code> 的古 DNA 思路呼应：<strong>别丢看似无信息的老样本，先升级读取方法</strong>。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/paleontology/index.md</code> ｜ 第39期 科学板块</p></blockquote><p>关键词：禾本科、Poaceae、禾草花粉、超分辨显微、半监督深度学习、卷积神经网络、CNN特征、Shannon熵、形态变异性、分类学多样性、C3与C4、光合类型判别、梯度提升决策树、肯尼亚山、25000年湖相沉积、末次冰期、21500-16000年前、多样性骤降、晚冰期全新世过渡、火活动、CO2浓度、花粉形态不可分辨、解码器升级</p><p>关联：<code>topics/paleontology/science-daily-2026-09-16.md</code>（侏罗纪声景重构——从化石结构读回行为/感官）、<code>topics/paleontology/science-daily-2026-10-08.md</code>（侏罗纪会游泳的哺乳形动物）、<code>topics/earth-science/science-daily-2026-10-12.md</code>（湖相沉积读生态史——同为&quot;沉积记录 + 新方法&quot;）</p>',10)])])}const _=t(r,[["render",a]]);export{u as __pageData,_ as default};
